    if inp != out:
        print(f"  Length change: {len(inp)} -> {len(out)}")
        # Show character by character
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Extra chars in output: {out[min_len:] if len(out) > min_len else inp[min_len:]}")
    print()

